function redirectFluid(cell){const around=[[1,0],[-1,0],[0,1],[0,-1]],source=around.map(([x,y])=>terrainInfo({x:cell.x+x,y:cell.y+y}).kind).find(k=>k==='lava'||k==='water');if(!source)return;state.blocks.fluids[cellKey(cell)]=source;const queue=[cell],seen=new Set([cellKey(cell)]);while(queue.length&&seen.size<80){const at=queue.shift(),surface=terrainSurface(at);around.forEach(([dx,dy])=>{const n={x:at.x+dx,y:at.y+dy},key=cellKey(n);if(seen.has(key)||!state.blocks.dug[key]||terrainSurface(n)>surface)return;seen.add(key);state.blocks.fluids[key]=source;queue.push(n)})}terrainDirty=true}
