function buildStarterHouse(){if(state.blocks.houseCreated)return;const cx=510,cy=505,halfW=6,halfD=4,cells=[];for(let x=cx-halfW;x<=cx+halfW;x++)for(let y=cy-halfD;y<=cy+halfD;y++)cells.push({x,y});const base=Math.max(...cells.map(terrainSurface)),add=(x,y,t,level)=>state.blocks.placed.push({x,y,t,level});cells.forEach(c=>{for(let h=terrainSurface(c);h<base;h++)add(c.x,c.y,'brick',h);add(c.x,c.y,'wood',base)});for(let level=base+1;level<=base+4;level++)for(let x=cx-halfW;x<=cx+halfW;x++)for(let y=cy-halfD;y<=cy+halfD;y++){if(x!==cx-halfW&&x!==cx+halfW&&y!==cy-halfD&&y!==cy+halfD)continue;let type='wood';if(y===cy+halfD&&Math.abs(x-cx)<=1&&level<=base+2)type='door';else if(level===base+2&&((y===cy-halfD&&[-4,0,4].includes(x-cx))||(x===cx-halfW||x===cx+halfW)&&[-2,2].includes(y-cy)))type='window';add(x,y,type,level)}for(let x=cx-halfW;x<=cx+halfW;x++)for(let y=cy-halfD;y<=cy+halfD;y++){const edge=Math.max(Math.abs(x-cx)/halfW,Math.abs(y-cy)/halfD);add(x,y,edge>.72?'brick':'wood',base+5)}for(let y=cy-halfD+1;y<=cy+halfD-1;y++)add(cx,y,'wood',base+1);state.blocks.houseCreated=true;placedDirty=true}
function buildBlockForest(){if(state.blocks.forestCreated)return;const spots=[[490,492],[498,490],[507,492],[518,493],[486,502],[526,504],[488,514],[498,520],[510,520],[523,516],[480,490],[535,492],[478,508],[538,512],[487,530],[502,534],[520,531],[535,526]],occupied=new Set(state.blocks.placed.map(b=>`${b.x},${b.y},${b.level??0}`)),add=(x,y,t,level)=>{const key=`${x},${y},${level}`;if(!occupied.has(key)){state.blocks.placed.push({x,y,t,level});occupied.add(key)}};spots.forEach(([x,y])=>{const base=terrainSurface({x,y});for(let h=0;h<4;h++)add(x,y,'wood',base+h);for(let dx=-1;dx<=1;dx++)for(let dy=-1;dy<=1;dy++)add(x+dx,y+dy,'grass',base+4);[[-1,0],[1,0],[0,-1],[0,1],[0,0]].forEach(([dx,dy])=>add(x+dx,y+dy,'grass',base+5));add(x,y,'grass',base+6)});state.blocks.forestCreated=true;placedDirty=true}
