function syncWorld3D(){if(!world3D)return;if(!playerTarget)playerTarget=new THREE.Vector3();playerTarget.set(state.blocks.x-500,0,state.blocks.y-500);rebuildTerrain();if(lastPlacedCount!==state.blocks.placed.length){placedDirty=true;lastPlacedCount=state.blocks.placed.length}if(placedDirty){placedGroup.children.forEach(disposeObject);placedGroup.clear();state.blocks.placed.slice(-MAX_PLACED_BLOCKS).forEach(b=>placedGroup.add(makePlaced(b)));placedDirty=false}const cell=targetCell(),level=nextLevel(cell);if(placementGhost){placementGhost.position.set(cell.x-500,level+.5,cell.y-500);placementGhost.visible=level<20}$('#blockScore').textContent=`🪵 ${state.blocks.wood||0} · 🚪 ${state.blocks.door||0} · 🪟 ${state.blocks.window||0}`;$$('[data-block]').forEach(b=>{b.classList.toggle('active',b.dataset.block===state.blocks.selected);const count=b.querySelector('small');if(count)count.textContent=state.blocks[b.dataset.block]||0});scheduleSave()}
function angleLerp(a,b,t){let d=(b-a+Math.PI)%(Math.PI*2)-Math.PI;return a+d*t}
function updateAnimalNeeds(now){const dt=Math.min(.25,(now-lastNeedTick)/1000);lastNeedTick=now;if(!$('#blocksScreen').classList.contains('active')||document.hidden)return;const adopted=state.blocks.adopted,s=adopted===null?null:state.blocks.animals[adopted];let death=false;if(s&&s.life>0){s.food=Math.max(0,s.food-dt*.055);s.water=Math.max(0,s.water-dt*.075);if(s.food<=0&&s.water<=0){const before=s.life;s.life=Math.max(0,s.life-dt*.18);death=before>0&&s.life<=0}}if(now-lastNeedsPaint>500){animalMeshes.forEach((a,i)=>updateAnimalLabel(a.userData.label,state.blocks.animals[i],adopted===i));$('#animalScore').textContent=adopted===null?'🐾 Procura um companheiro':`${s.life>0?'⭐':'💀'} Companheiro: ${worldAnimals[adopted].name}`;lastNeedsPaint=now}if(now-lastNeedsSave>5000){save();lastNeedsSave=now}if(death){$('#blockTip').textContent=`O teu companheiro ${worldAnimals[adopted].name} ficou sem vida 💔`;tone(120,.3)}}
function animateAnimal(a,i,t){const stats=state.blocks.animals[i];if(stats.life<=0){a.rotation.z=angleLerp(a.rotation.z,Math.PI/2,.035);a.position.y=.2;return}a.rotation.z=angleLerp(a.rotation.z,0,.08);const offer=offeringForAnimal(i),companion=state.blocks.adopted===i,playerDist=Math.hypot(a.position.x-player3D.position.x,a.position.z-player3D.position.z),dir=state.blocks.dir||{x:0,y:-1};let targetX=offer?offer.x-500:companion?player3D.position.x-dir.x*2.2:a.userData.targetX,targetZ=offer?offer.y-500:companion?player3D.position.z-dir.y*2.2:a.userData.targetZ,dx=targetX-a.position.x,dz=targetZ-a.position.z,dist=Math.hypot(dx,dz);if(!offer&&!companion&&dist<2){a.userData.targetX=Math.random()*920-460;a.userData.targetZ=Math.random()*920-460;targetX=a.userData.targetX;targetZ=a.userData.targetZ;dx=targetX-a.position.x;dz=targetZ-a.position.z;dist=Math.hypot(dx,dz)}if(offer&&dist<.75){const bi=state.blocks.placed.indexOf(offer);if(bi>=0)state.blocks.placed.splice(bi,1);stats[offer.t]=Math.min(100,stats[offer.t]+45);celebrate(true);tone(720,.15);$('#blockTip').textContent=`O ${worldAnimals[i].name} consumiu ${offer.t==='food'?'comida':'água'}! A barra aumentou ❤️`;syncWorld3D();return}const shouldMove=offer?dist>.75:companion?dist>.55:playerDist>6;if(shouldMove&&dist){const speed=companion?Math.min(.3,.07+dist*.012):offer?a.userData.speed*2.8:a.userData.speed;a.position.x+=dx/dist*speed;a.position.z+=dz/dist*speed;a.rotation.y=angleLerp(a.rotation.y,Math.atan2(dx,dz),.08)}else if(playerDist<=6)a.rotation.y=angleLerp(a.rotation.y,Math.atan2(player3D.position.x-a.position.x,player3D.position.z-a.position.z),.08);a.position.y=Math.abs(Math.sin(t*(shouldMove?7:2)+a.userData.phase))*.055;a.userData.heart.rotation.y=t*2;a.userData.heart.position.y=a.userData.markerY+Math.sin(t*3+i)*.08;a.userData.needMarker.position.y=a.userData.markerY+Math.sin(t*3+i)*.08}
function animateWorld(){requestAnimationFrame(animateWorld);if(!worldRenderer)return;const now=performance.now();if(!$('#blocksScreen').classList.contains('active')||document.hidden){lastNeedTick=now;return}const canvas=worldRenderer.domElement,w=canvas.clientWidth||440,h=canvas.clientHeight||440;if(canvas.width!==Math.floor(w*Math.min(devicePixelRatio,2))||canvas.height!==Math.floor(h*Math.min(devicePixelRatio,2))){worldRenderer.setSize(w,h,false);worldCamera.aspect=w/h;worldCamera.updateProjectionMatrix()}const t=now/1000,moving=now<playerMoveUntil;if(playerTarget){player3D.position.x+=(playerTarget.x-player3D.position.x)*.38;player3D.position.z+=(playerTarget.z-player3D.position.z)*.38}player3D.rotation.y=angleLerp(player3D.rotation.y,playerTurn,.35);starMeshes.forEach((s,i)=>{s.rotation.y=t*1.8+i;s.position.y=terrainInfo({x:worldStars[i][0],y:worldStars[i][1]}).height+1.3+Math.sin(t*2+i)*.18});supplyMeshes.forEach(s=>{s.rotation.y=t*1.4+s.userData.index;s.position.y=Math.max(.65,terrainInfo({x:Math.round(s.position.x+500),y:Math.round(s.position.z+500)}).height+.65)+Math.sin(t*2+s.userData.phase)*.18});const a=moving?Math.sin(t*13)*.8:Math.sin(t*2)*.04,groundY=terrainSurface({x:state.blocks.x,y:state.blocks.y});if(player3D.userData.leftArm){player3D.userData.leftArm.rotation.x=a;player3D.userData.rightArm.rotation.x=-a;player3D.userData.leftLeg.rotation.x=-a;player3D.userData.rightLeg.rotation.x=a;player3D.rotation.z=moving?Math.sin(t*13)*.025:0;player3D.position.y+=(groundY+(moving?Math.abs(Math.sin(t*13))*.09:0)-player3D.position.y)*.22}const target=new THREE.Vector3(player3D.position.x-20,player3D.position.y+18,player3D.position.z+25);worldCamera.position.lerp(target,.1);worldCamera.lookAt(player3D.position.x,player3D.position.y+1,player3D.position.z);worldRenderer.render(worldScene,worldCamera)}
function movePlayer(dx,dy){state.blocks.dir={x:dx,y:dy};state.blocks.x=Math.max(2,Math.min(998,state.blocks.x+dx));state.blocks.y=Math.max(2,Math.min(998,state.blocks.y+dy));playerMoveUntil=performance.now()+180;playerTurn=dx?dx>0?Math.PI/2:-Math.PI/2:dy>0?0:Math.PI;let found=false;worldStars.forEach((p,i)=>{if(Math.abs(p[0]-state.blocks.x)<=1&&Math.abs(p[1]-state.blocks.y)<=1&&!state.blocks.collected.includes(i)){state.blocks.collected.push(i);['grass','dirt','brick','wood','water','flower'].forEach(type=>state.blocks[type]=(state.blocks[type]||0)+100);found=true;celebrate(true);tone(880,.18);$('#blockTip').textContent=state.blocks.collected.length===worldStars.length?'Encontraste as 100 estrelas! Grande explorador! 🏆':'Estrela encontrada: +100 de todos os blocos! ⭐'}});supplyMeshes.forEach(s=>{if(!s.visible||Math.hypot(s.position.x-(state.blocks.x-500),s.position.z-(state.blocks.y-500))>3)return;const type=s.userData.type;if(['pickaxe','shovel','axe'].includes(type)){state.blocks.tools[type]=true;state.blocks.selectedTool=type;s.visible=false;found=true;celebrate(true);tone(760,.16);const names={pickaxe:'picareta ⛏️',shovel:'pá 🥄',axe:'machado 🪓'};$('#blockTip').textContent=`Encontraste a ${names[type]}! Já podes usá-la.`;return}if(type==='wood'&&(!state.blocks.tools.axe||state.blocks.selectedTool!=='axe')){$('#blockTip').textContent='Encontraste madeira. Seleciona o machado para a cortar! 🪓';return}state.blocks[type]=(state.blocks[type]||0)+1;found=true;tone(560,.1);const labels={water:'água 💧',brick:'pedra 🪨',grass:'relva 🌿',flower:'flor 🌼',wood:'madeira 🪵'};$('#blockTip').textContent=`Recolheste ${labels[type]}!`;spawnSupply(s,type)});syncWorld3D()}
const movePlayerBase=movePlayer;movePlayer=(dx,dy)=>{movePlayerBase(dx,dy);if(!worldScene)return;const px=state.blocks.x-500,pz=state.blocks.y-500,rock=worldScene.children.find(o=>o.visible&&o.geometry?.type==='DodecahedronGeometry'&&Math.hypot(o.position.x-px,o.position.z-pz)<=3);if(rock){state.blocks.brick=(state.blocks.brick||0)+1;rock.position.set(Math.random()*900-450,.45,Math.random()*900-450);$('#blockTip').textContent='Recolheste uma pedra! 🪨 +1 bloco';tone(560,.1);syncWorld3D()}};
function targetCell(){const d=state.blocks.dir||{x:0,y:-1};return{x:state.blocks.x+d.x,y:state.blocks.y+d.y}}
function placeBlock(){const cell=targetCell(),level=nextLevel(cell),type=state.blocks.selected;if(state.blocks.placed.length>=MAX_PLACED_BLOCKS){$('#blockTip').textContent='O mundo atingiu o limite seguro de construções. Remove alguns blocos para continuar.';tone(180,.09);return}if((state.blocks[type]||0)<=0){$('#blockTip').textContent='Já não tens unidades deste objeto. Recolhe ou escava mais pelo mapa!';tone(180,.09);return}if(level>=60){$('#blockTip').textContent='Chegaste ao limite máximo de 60 blocos de altura!';tone(180,.08);return}state.blocks.placed.push({...cell,t:type,level});delete state.blocks.fluids[cellKey(cell)];state.blocks[type]--;placedDirty=terrainDirty=true;$('#blockTip').textContent=level<terrainInfo(cell).height?'Preencheste uma camada escavada do terreno!':(level?`Bloco empilhado na altura ${level+1}! 🧱`:'Bloco colocado! Agora podes pôr outro por cima.');tone(430,.08);syncWorld3D()}
function removeBlock(){const cell=targetCell(),key=cellKey(cell),blocks=cellBlocks(cell);if(blocks.length){const top=blocks.reduce((a,b)=>(b.level??0)>(a.level??0)?b:a),i=state.blocks.placed.indexOf(top);state.blocks.placed.splice(i,1);state.blocks[top.t]=(state.blocks[top.t]||0)+1;placedDirty=true;$('#blockTip').textContent=`Recolheste 1 bloco de ${top.t}!`;tone(300,.08);syncWorld3D();return}const info=terrainInfo(cell);if(info.liquid){state.blocks[info.kind]=(state.blocks[info.kind]||0)+1;state.blocks.drained[key]=true;delete state.blocks.fluids[key];terrainDirty=true;$('#blockTip').textContent=`Recolheste 1 bloco de ${info.kind==='water'?'água 💧':'lava 🔥'}!`;tone(360,.1);syncWorld3D();return}const depth=digDepth(cell);if(depth>=20||terrainSurface(cell)<=-19){$('#blockTip').textContent='Chegaste à rocha-mãe no nível -20.';tone(130,.12);return}const material=terrainMaterial(cell),layer=material==='sand'?'sand':material==='grass'?'grass':material==='dirt'?'dirt':'brick';state.blocks.dug[key]=depth+1;state.blocks[layer]=(state.blocks[layer]||0)+1;redirectFluid(cell);terrainDirty=true;const names={sand:'areia 🟨',grass:'relva 🌿',dirt:'terra 🟫',brick:'pedra 🪨'};$('#blockTip').textContent=`Recolheste 1 bloco de ${names[layer]}!`;tone(layer==='brick'?240:330,.1);syncWorld3D()}
function adoptNearby(){if(state.blocks.adopted!==null)return;const near=nearbyAnimal();if(!near){$('#blockTip').textContent='Aproxima-te mais de um animal para o adotar.';return}state.blocks.adopted=near.i;state.blocks.animals[near.i]={food:100,water:100,life:100};celebrate(true);tone(760,.18);$('#blockTip').textContent=`Adotaste o ${near.a.name}! Agora ele será o teu companheiro ⭐`;syncWorld3D()}
function releaseCompanion(){const i=state.blocks.adopted;if(i===null)return;const name=worldAnimals[i].name;state.blocks.animals[i]={food:100,water:100,life:100};animalMeshes[i].rotation.z=0;state.blocks.adopted=null;$('#releaseConfirm').classList.add('hidden');$('#blockTip').textContent=`Libertaste o ${name}. Aproxima-te de outro animal para o adotar!`;tone(480,.12);syncWorld3D()}
