function tradeWood(type,cost){if((state.blocks.wood||0)<cost){$('#blockTip').textContent=`Precisas de ${cost} blocos de madeira para esta troca.`;tone(180,.1);return}state.blocks.wood-=cost;state.blocks[type]=(state.blocks[type]||0)+1;state.blocks.selected=type;$('#blockTip').textContent=`Troca concluída: ${cost} madeiras por ${type==='door'?'uma porta 🚪':'uma janela 🪟'}!`;celebrate(true);tone(720,.14);syncWorld3D()}

function updateMessage(text,type=''){const box=$('#updateStatus');box.textContent=text;box.className=`update-status ${type}`;clearTimeout(updateMessage.timer);updateMessage.timer=setTimeout(()=>box.classList.add('hidden'),4200)}
async function getRemoteVersion(){const response=await fetch(`./version.json?t=${Date.now()}`,{cache:'no-store'});if(!response.ok)throw new Error('version');return(await response.json()).version}
function reloadUpdated(version=''){if(reloading)return;reloading=true;save();const url=new URL(location.href);if(version)url.searchParams.set('updated',version);location.replace(url.href)}
function activateWaitingWorker(){const worker=swRegistration?.waiting;if(worker)worker.postMessage('SKIP_WAITING')}
async function checkUpdate(){manualUpdate=true;updateFound=false;updateMessage('🔎 A procurar uma nova versão…');try{if(!swRegistration)await setupUpdates();if(!swRegistration)throw new Error('service-worker');const remote=await getRemoteVersion();await swRegistration.update();activateWaitingWorker();if(remote!==APP_VERSION){updateFound=true;updateMessage(`🦕 Versão ${remote} encontrada. A instalar…`);setTimeout(()=>{if(!reloading)reloadUpdated(remote)},8000)}else setTimeout(()=>{if(!updateFound)updateMessage(`✅ Já tens a versão mais recente · v${APP_VERSION}`,'good')},700)}catch(e){updateMessage(navigator.onLine?'Não foi possível verificar agora. Tenta novamente.':'Liga a internet e tenta novamente','bad')}}
async function setupUpdates(){if(!('serviceWorker'in navigator)||location.hostname==='localhost'||location.hostname==='127.0.0.1')return;if(updateSetupPromise)return updateSetupPromise;updateSetupPromise=(async()=>{navigator.serviceWorker.addEventListener('controllerchange',()=>reloadUpdated());swRegistration=await navigator.serviceWorker.register('./sw.js',{updateViaCache:'none'});swRegistration.addEventListener('updatefound',()=>{updateFound=true;const worker=swRegistration.installing;updateMessage('🦕 Nova versão encontrada. A instalar…');worker?.addEventListener('statechange',()=>{if(worker.state==='installed'){updateMessage('✅ Atualização instalada. A reiniciar…','good');activateWaitingWorker()}})});activateWaitingWorker();await swRegistration.update();setInterval(()=>swRegistration?.update().catch(()=>{}),5*60*1000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)swRegistration?.update().then(activateWaitingWorker).catch(()=>{})});addEventListener('online',()=>swRegistration?.update().then(activateWaitingWorker).catch(()=>{}))})().catch(e=>{swRegistration=null;updateSetupPromise=null;throw e});return updateSetupPromise}

