const platformScript=document.createElement('script');platformScript.src='platform.js?v=14';document.body.appendChild(platformScript);
$$('[data-trade]').forEach(b=>b.onclick=()=>tradeWood(b.dataset.trade,Number(b.dataset.cost)));const keyMoves={ArrowUp:'up',w:'up',ArrowDown:'down',s:'down',ArrowLeft:'left',a:'left',ArrowRight:'right',d:'right'};let activeMove=null,moveDelay=null,moveTimer=null;function movementStep(m){const delta={up:[0,-1],down:[0,1],left:[-1,0],right:[1,0]}[m];if(delta)movePlayer(delta[0],delta[1])}function clearMovement(){activeMove=null;clearTimeout(moveDelay);clearInterval(moveTimer);moveDelay=null;moveTimer=null}function beginMoving(m){if(activeMove===m)return;clearMovement();activeMove=m;movementStep(m);moveDelay=setTimeout(()=>{if(activeMove!==m)return;moveTimer=setInterval(()=>{if(activeMove===m)movementStep(m)},95)},260)}function stopMoving(m){if(!m||activeMove===m)clearMovement()}$$('[data-move]').forEach(b=>{const m=b.dataset.move;b.onclick=null;b.oncontextmenu=e=>e.preventDefault();b.onpointerdown=e=>{e.preventDefault();try{b.setPointerCapture(e.pointerId)}catch{}beginMoving(m)};const stop=e=>{e?.preventDefault?.();stopMoving(m)};b.onpointerup=stop;b.onpointercancel=stop;b.onlostpointercapture=stop});addEventListener('keydown',e=>{const m=keyMoves[e.key];if(m&&$('#blocksScreen').classList.contains('active')){e.preventDefault();if(!e.repeat)beginMoving(m)}});addEventListener('keyup',e=>{const m=keyMoves[e.key];if(m)stopMoving(m)});addEventListener('blur',clearMovement);document.addEventListener('visibilitychange',()=>{if(document.hidden)clearMovement()});addEventListener('beforeunload',save);$('#worldBack').onclick=()=>{if(document.fullscreenElement)document.exitFullscreen?.();clearMovement();save();$('#resetConfirm').classList.add('hidden');show('menuScreen');updateMenu()};$('#fullscreenWorld').onclick=()=>{if(document.fullscreenElement)document.exitFullscreen?.();else $('#blocksScreen').requestFullscreen?.()};
